numbers = [2, 4, 6, 8, 10]
target = 8

def binary_find(numbers, target):
    low = 0
    high = len(numbers) - 1
    while low <= high:
        middle = (low + high) // 2
        if numbers[middle] == target:
            return True
        elif numbers[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return False

print(binary_find(numbers, target))

