from collections import deque
graph = {"home": ["shop"], "shop": ["park"], "park": []}
start = "home"
goal = "park"
queue = deque([(start, 0)])
visited = {start}
answer = -1
while queue:
    place, steps = queue.popleft()
    if place == goal:
        answer = steps
        break
    for neighbor in graph.get(place, []):
        if neighbor not in visited:
            visited.add(neighbor)
            queue.append((neighbor, steps + 1))
print(answer)

